353	func (req IssueRequest) validatePresent() error {
354		missing := []string{}
355		if strings.TrimSpace(req.Operator) == "" {
356			missing = append(missing, "operator")
357		}
358		if strings.TrimSpace(req.Reason) == "" {
359			missing = append(missing, "reason")
360		}
361		if strings.TrimSpace(req.RequestID) == "" {
362			missing = append(missing, "request_id")
363		}
364		if strings.TrimSpace(req.ItemID) == "" {
365			missing = append(missing, "item_id")
366		}
367		if strings.TrimSpace(req.SeriesID) == "" {
368			missing = append(missing, "series_id")
369		}
370		if strings.TrimSpace(req.BatchNo) == "" {
371			missing = append(missing, "batch_no")
372		}
373		if strings.TrimSpace(req.HolderID) == "" {
374			missing = append(missing, "holder_id")
375		}
376		if len(missing) > 0 {
377			return fmt.Errorf("%w: 发行请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
378		}
379		return nil
380	}
