780	func createAuthzParamsSig(req CreateAuthorizationRequest) string {
781		// Price 用 omitempty：价款为 0 时签名与旧格式一致，旧授权创建请求
782		// 仍可回放；改价则按请求号冲突拒绝。
783		b, _ := json.Marshal(struct {
784			Kind          string `json:"kind"`
785			AuthID        string `json:"auth_id"`
786			ItemID        string `json:"item_id"`
787			TrusteeID     string `json:"trustee_id"`
788			ToID          string `json:"to_id"`
789			ExpectedOwner string `json:"expected_owner"`
790			ExpectedVer   int64  `json:"expected_version"`
791			ExpiresAt     string `json:"expires_at"`
792			Price         int64  `json:"price,omitempty"`
793			Reason        string `json:"reason"`
794		}{"auth_create", req.AuthID, req.ItemID, req.TrusteeID, req.ToID,
795			req.ExpectedOwner, req.ExpectedVer,
796			req.ExpiresAt.UTC().Format(time.RFC3339Nano), req.Price, req.Reason})
797		return string(b)
798	}
799	
800	// CreateAuthorization 由当前持有人为一件已发行藏品创建限时、一次性的
801	// 代转授权：指定唯一授权编号、受托账户、固定接收账户、绝对到期时间，
802	// 以及期望持有人与期望版本。授权绑定创建时的持有版本，不改变持有关系，
803	// 也不限制持有人继续直接转让。受托人不能是授权人；受托人可与接收人
804	// 相同，但接收人也不能是授权人。到期时间必须晚于当前时间。
805	//
806	// 请求号与发行、转让共用同一操作者的请求号范围：相同业务参数重提返回
807	// 首次结果（成功或状态类业务拒绝），参数变化返回 ErrRequestConflict；
808	// 参数错误与引用不存在不占用请求号。
809	//
810	// 成功与状态类拒绝都以保存完成为准：本次结果尚未写入原登记册而保存失败
811	// （如数据位置暂时无法写入）时，返回实际保存错误，不报告创建成功，也不
812	// 只返回原业务拒绝；结果为空（授权编号与状态为空、绑定版本为零、不标
813	// 回放、业务错误为空），error 说明保存失败。即使失败后原数据暂时无法
814	// 读取、状态未能按磁盘重建，这次操作也不留下任何新增授权、创建记录或
815	// 请求号占用，授权历史序号不被消耗，后续其他操作成功保存也不会把这次
816	// 未保存的内容带进登记册。保存条件恢复后用完全相同的请求重提，按当时
817	// 的业务状态重新判断：拒绝条件仍在则重新保存此次拒绝并返回对应业务
818	// 错误（首次重提不标回放），状态已满足请求则正常创建。
819	func (r *Registry) CreateAuthorization(req CreateAuthorizationRequest) (CreateAuthorizationResult, error) {
820		if err := req.validatePresent(); err != nil {
821			return CreateAuthorizationResult{}, err
822		}
823		r.mu.Lock()
824		defer r.mu.Unlock()
825		if err := r.checkOpen(); err != nil {
826			return CreateAuthorizationResult{}, err
827		}
828	
829		now := r.now()
830		key := requestKey(req.Operator, req.RequestID)
831		sig := createAuthzParamsSig(req)
832		if prev, ok := r.state.Requests[key]; ok {
833			return r.replayCreateAuthz(prev, sig)
834		}
835	
836		if bizErr := r.checkCreateAuthorization(req, now); bizErr != nil {
837			if !isValidationErr(bizErr) {
838				// 状态类业务拒绝（编号占用、停用、同人、版本不符、到期时间
839				// 已过等）占用请求号并落盘；参数错误与引用不存在不占用。
840				r.state.Requests[key] = request{
841					Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
842					Params: sig, Rejected: true, Reason: errCode(bizErr),
843					AuthID: req.AuthID, ItemID: req.ItemID,
844				}
845				if err := r.commit(); err != nil {
846					// 拒绝结果落盘失败：这次拒绝没有被记住，与发行、转让一致——
847					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
848					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
849					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
850					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
851					// 的情形。整体返回空结果：授权编号与状态为空、绑定版本
852					// 为零、不标回放、结果中业务错误为空，error 保留实际
853					// 写入错误。
854					delete(r.state.Requests, key)
855					return CreateAuthorizationResult{}, err
856				}
857			}
858			return CreateAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
859		}
860	
861		h := r.state.Holdings[req.ItemID]
862		a := authzRec{
863			ID: req.AuthID, ItemID: req.ItemID, GranterID: req.Operator,
864			TrusteeID: req.TrusteeID, ToID: req.ToID, ExpiresAt: req.ExpiresAt,
865			GrantVer: h.Version, Price: req.Price, CreatedAt: now,
866		}
867		// 回滚基点：保存失败且磁盘暂时不可读、状态未能按磁盘重建时，本次
868		// 未保存的授权、创建记录与请求号占用都必须显式撤销，否则后续任何
869		// 一次成功保存都会把这份未保存的授权带进登记册。
870		prevAuthSeq := r.state.NextAuthSeq
871		prevEvents := len(r.state.AuthEvents)
872		r.state.Authzs[req.AuthID] = a
873		authSeq := prevAuthSeq + 1
874		r.state.NextAuthSeq = authSeq
875		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
876			Seq: authSeq, AuthID: req.AuthID, ItemID: req.ItemID, Kind: "create",
877			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
878			FromStatus: "", ToStatus: AuthActive, OccurredAt: now,
879		})
880		r.state.Requests[key] = request{
881			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
882			Params: sig, AuthID: req.AuthID, ItemID: req.ItemID, Version: h.Version,
883		}
884		if err := r.commit(); err != nil {
885			// commit 失败时已尝试按磁盘内容重建状态：重建成功则本次改动已
886			// 随旧状态整体撤销（请求记录不存在），无需再动；磁盘暂时不可读、
887			// 状态未能重建时请求记录仍在，据此把本次未保存的改动全部撤销。
888			if _, ok := r.state.Requests[key]; ok {
889				delete(r.state.Requests, key)
890				delete(r.state.Authzs, req.AuthID)
891				r.state.AuthEvents = r.state.AuthEvents[:prevEvents]
892				r.state.NextAuthSeq = prevAuthSeq
893			}
894			return CreateAuthorizationResult{}, err
895		}
896		return CreateAuthorizationResult{AuthID: req.AuthID, Status: AuthActive, GrantVer: h.Version}, nil
897	}
898	
899	func (r *Registry) checkCreateAuthorization(req CreateAuthorizationRequest, now time.Time) error {
900		h, ok := r.state.Holdings[req.ItemID]
901		if !ok {
902			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
903				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
904			}
905			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
906		}
907		op, ok := r.state.Accounts[req.Operator]
908		if !ok {
909			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, req.Operator)
910		}
911		trustee, ok := r.state.Accounts[req.TrusteeID]
912		if !ok {
913			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.TrusteeID)
914		}
915		to, ok := r.state.Accounts[req.ToID]
916		if !ok {
917			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, req.ToID)
918		}
919		if req.TrusteeID == req.Operator {
920			return fmt.Errorf("%w: 受托人不能是授权人 %s", ErrSameAccount, req.Operator)
921		}
922		if req.ToID == req.Operator {
923			return fmt.Errorf("%w: 接收人不能是授权人 %s", ErrSameAccount, req.Operator)
924		}
925		if !op.Active {
926			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, req.Operator)
927		}
928		if !trustee.Active {
929			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.TrusteeID)
930		}
931		if !to.Active {
932			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, req.ToID)
933		}
934		// 授权编号占用是对象级冲突，优先于当前时间与持有版本检查。
935		if _, exists := r.state.Authzs[req.AuthID]; exists {
936			return fmt.Errorf("%w: 授权编号 %s 已被占用", ErrAlreadyExists, req.AuthID)
937		}
938		// 到期时间不晚于当前时间即为参数错误；从到期时间点起不可使用。
939		if !req.ExpiresAt.After(now) {
940			return fmt.Errorf("%w: 到期时间 %s 必须晚于当前时间",
941				ErrInvalidArgument, req.ExpiresAt.Format(time.RFC3339Nano))
942		}
943		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
944			req.Operator != h.OwnerID {
945			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d",
946				ErrConflict, req.ItemID, h.OwnerID, h.Version)
947		}
948		return nil
949	}
