1380	func (r *Registry) replayProxyTransfer(prev request, sig string) (ProxyTransferResult, error) {
1381		if prev.Kind != "proxy_transfer" || prev.Params != sig {
1382			return ProxyTransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1383				ErrRequestConflict, prev.Operator, prev.RequestID)
1384		}
1385		res := ProxyTransferResult{AuthID: prev.AuthID, ItemID: prev.ItemID, FromID: prev.FromID,
1386			ToID: prev.ToID, Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
1387		if prev.Rejected {
1388			res.Err = codeErr(prev.Reason)
1389			return res, res.Err
1390		}
1391		// 回放首次成功的金额：授权到期、账户停用或藏品再次易手后仍返回
1392		// 原价款与应付明细，不重复计入。
1393		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
1394		return res, nil
1395	}
