1397	// ---- 授权查询 ----
1398	
1399	// GetAuthorization 按编号查询授权内容与撤销、使用状态。授权不存在时
1400	// 返回包裹 ErrNotFound 的错误；返回的 Status 按当前时间实时计算，
1401	// 到期但尚未终结的授权返回 AuthExpired。
1402	func (r *Registry) GetAuthorization(authID string) (Authorization, error) {
1403		r.mu.Lock()
1404		defer r.mu.Unlock()
1405		if err := r.checkOpen(); err != nil {
1406			return Authorization{}, err
1407		}
1408		a, ok := r.state.Authzs[authID]
1409		if !ok {
1410			return Authorization{}, fmt.Errorf("%w: 授权 %s", ErrNotFound, authID)
1411		}
1412		return Authorization{
1413			ID: a.ID, ItemID: a.ItemID, GranterID: a.GranterID, TrusteeID: a.TrusteeID,
1414			ToID: a.ToID, ExpiresAt: a.ExpiresAt, GrantVer: a.GrantVer, Price: a.Price,
1415			Status:    authzCurrentStatus(a, r.now()),
1416			UsedTxSeq: a.UsedTxSeq, UsedAt: a.UsedAt, CreatedAt: a.CreatedAt,
1417			RevokedAt: a.RevokedAt,
1418		}, nil
1419	}
1420	
1421	// AuthorizationHistory 按藏品查看授权变更记录（创建、撤销、使用），
1422	// 按发生先后排列；每条记录包含操作者、原因、请求号与前后状态。藏品
1423	// 不存在时返回包裹 ErrNotFound 的错误。
1424	func (r *Registry) AuthorizationHistory(itemID string) ([]AuthorizationEvent, error) {
1425		r.mu.Lock()
1426		defer r.mu.Unlock()
1427		if err := r.checkOpen(); err != nil {
1428			return nil, err
1429		}
1430		if _, ok := r.state.Items[itemID]; !ok {
1431			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1432		}
1433		out := make([]AuthorizationEvent, 0)
1434		for _, e := range r.state.AuthEvents {
1435			if e.ItemID != itemID {
1436				continue
1437			}
1438			out = append(out, AuthorizationEvent{
1439				Seq: e.Seq, AuthID: e.AuthID, ItemID: e.ItemID, Kind: e.Kind,
1440				Operator: e.Operator, Reason: e.Reason, RequestID: e.RequestID,
1441				FromStatus: e.FromStatus, ToStatus: e.ToStatus, TxSeq: e.TxSeq,
1442				OccurredAt: e.OccurredAt,
1443			})
1444		}
1445		return out, nil
1446	}
1447	
1448	// ---- 查询 ----
1449	
1450	// GetItem 查询单件藏品的静态登记信息；不存在时返回包裹 ErrNotFound 的错误。
1451	func (r *Registry) GetItem(id string) (Item, error) {
1452		r.mu.Lock()
1453		defer r.mu.Unlock()
1454		if err := r.checkOpen(); err != nil {
1455			return Item{}, err
1456		}
1457		it, ok := r.state.Items[id]
1458		if !ok {
1459			return Item{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, id)
1460		}
1461		return Item{ID: it.ID, SeriesID: it.SeriesID, BatchNo: it.BatchNo,
1462			Metadata: it.Metadata, IssuedTxID: it.IssuedTxID}, nil
1463	}
1464	
1465	// GetHolding 查询藏品当前持有状态；藏品不存在时返回包裹 ErrNotFound 的错误。
1466	func (r *Registry) GetHolding(itemID string) (Holding, error) {
1467		r.mu.Lock()
1468		defer r.mu.Unlock()
1469		if err := r.checkOpen(); err != nil {
1470			return Holding{}, err
1471		}
1472		h, ok := r.state.Holdings[itemID]
1473		if !ok {
1474			return Holding{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1475		}
1476		return Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version}, nil
1477	}
1478	
1479	// HoldingsOf 查询某账户当前持有的全部藏品。账户不存在时返回包裹
1480	// ErrNotFound 的错误；停用账户仍可正常查询。
1481	func (r *Registry) HoldingsOf(accountID string) ([]Holding, error) {
1482		r.mu.Lock()
1483		defer r.mu.Unlock()
1484		if err := r.checkOpen(); err != nil {
1485			return nil, err
1486		}
1487		if _, ok := r.state.Accounts[accountID]; !ok {
1488			return nil, fmt.Errorf("%w: 账户 %s", ErrNotFound, accountID)
1489		}
1490		out := make([]Holding, 0)
1491		for _, h := range r.state.Holdings {
1492			if h.OwnerID == accountID {
1493				out = append(out, Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version})
1494			}
1495		}
1496		sort.Slice(out, func(i, j int) bool { return out[i].ItemID < out[j].ItemID })
1497		return out, nil
1498	}
1499	
1500	// History 查询藏品的发行与历次成功转让，按发生先后排列。发行记录的
1501	// 前持有人为空、前版本为 0。重复提交不会产生额外历史。藏品不存在时
1502	// 返回包裹 ErrNotFound 的错误。
1503	func (r *Registry) History(itemID string) ([]HistoryEntry, error) {
1504		r.mu.Lock()
1505		defer r.mu.Unlock()
1506		if err := r.checkOpen(); err != nil {
1507			return nil, err
1508		}
1509		if _, ok := r.state.Items[itemID]; !ok {
1510			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1511		}
1512		out := make([]HistoryEntry, 0)
1513		for _, e := range r.state.History {
1514			if e.ItemID != itemID {
1515				continue
1516			}
1517			out = append(out, HistoryEntry{
1518				Seq: e.Seq, Kind: e.Kind, ItemID: e.ItemID, Operator: e.Operator,
1519				Reason: e.Reason, RequestID: e.RequestID, FromID: e.FromID, ToID: e.ToID,
1520				FromVersion: e.FromVersion, ToVersion: e.ToVersion, AuthID: e.AuthID,
1521			})
1522		}
1523		return out, nil
1524	}
1525	
1526	// ---- 幂等辅助 ----
1527	
1528	// requestKey 由完整的操作者账户编号与完整的请求号共同确定一条请求记录。
1529	// 采用 JSON 数组编码而非直接拼接：账户编号或请求号本身允许包含零字符
1530	// （U+0000）等任意字符，直接拼接会让 ("a", "b\x00c") 与 ("a\x00b", "c")
1531	// 之类不同的组合得到相同的键，导致不同账户互相占用请求号、回放别人的
1532	// 结果。JSON 编码对任意字符都无歧义，两个组成部分各自完整参与键的构成。
1533	func requestKey(operator, requestID string) string {
1534		b, _ := json.Marshal([2]string{operator, requestID})
1535		return string(b)
1536	}
1537	
1538	// isValidationErr 判定是否为请求本身不成立的错误：必填缺失，或引用了
1539	// 不存在的账户、系列、藏品。这类请求不占用请求号、不落任何记录，引用
1540	// 对象后来补建后仍可用原请求号完整执行一次；其余拒绝（封存、停用、
1541	// 版本冲突、无权、编号已用、收发同人等状态类业务拒绝）按首次结果记忆
1542	// 并回放。
1543	func isValidationErr(err error) bool {
1544		return errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrNotFound)
1545	}
1546	
1547	var errCodes = map[error]string{
1548		ErrNotFound:             "not_found",
1549		ErrAlreadyExists:        "already_exists",
1550		ErrAccountInactive:      "account_inactive",
1551		ErrSeriesSealed:         "series_sealed",
1552		ErrConflict:             "conflict",
1553		ErrSameAccount:          "same_account",
1554		ErrForbidden:            "forbidden",
1555		ErrAuthorizationRevoked: "authorization_revoked",
1556		ErrAuthorizationExpired: "authorization_expired",
1557		ErrAuthorizationUsed:    "authorization_used",
1558		ErrRoyaltyFrozen:        "royalty_frozen",
1559		ErrSplitIntentRejected:  "split_intent_rejected",
1560		ErrSplitIntentWithdrawn: "split_intent_withdrawn",
1561		ErrSplitIntentInvalid:   "split_intent_invalid",
1562		ErrSplitIntentExpired:   "split_intent_expired",
1563		ErrSplitAnswered:        "split_answered",
1564	}
1565	
1566	var codeErrs = map[string]error{
1567		"not_found":              ErrNotFound,
1568		"already_exists":         ErrAlreadyExists,
1569		"account_inactive":       ErrAccountInactive,
1570		"series_sealed":          ErrSeriesSealed,
1571		"conflict":               ErrConflict,
1572		"same_account":           ErrSameAccount,
1573		"forbidden":              ErrForbidden,
1574		"authorization_revoked":  ErrAuthorizationRevoked,
1575		"authorization_expired":  ErrAuthorizationExpired,
1576		"authorization_used":     ErrAuthorizationUsed,
1577		"royalty_frozen":         ErrRoyaltyFrozen,
1578		"split_intent_rejected":  ErrSplitIntentRejected,
1579		"split_intent_withdrawn": ErrSplitIntentWithdrawn,
1580		"split_intent_invalid":   ErrSplitIntentInvalid,
1581		"split_intent_expired":   ErrSplitIntentExpired,
1582		"split_answered":         ErrSplitAnswered,
1583	}
1584	
1585	func errCode(err error) string {
1586		for sentinel, code := range errCodes {
1587			if errors.Is(err, sentinel) {
1588				return code
1589			}
1590		}
1591		return "rejected"
1592	}
1593	
1594	func codeErr(code string) error {
1595		if e, ok := codeErrs[code]; ok {
1596			return e
1597		}
1598		return errors.New("registry: 请求曾被拒绝")
1599	}
