1	package registry
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"strings"
7	)
8	
9	// ---- 整批发行 ----
10	
11	func (req IssueBatchRequest) validatePresent() error {
12		missing := []string{}
13		if strings.TrimSpace(req.Operator) == "" {
14			missing = append(missing, "operator")
15		}
16		if strings.TrimSpace(req.Reason) == "" {
17			missing = append(missing, "reason")
18		}
19		if strings.TrimSpace(req.RequestID) == "" {
20			missing = append(missing, "request_id")
21		}
22		if strings.TrimSpace(req.SeriesID) == "" {
23			missing = append(missing, "series_id")
24		}
25		if strings.TrimSpace(req.BatchNo) == "" {
26			missing = append(missing, "batch_no")
27		}
28		if len(missing) > 0 {
29			return fmt.Errorf("%w: 整批发行请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
30		}
31		if len(req.Entries) == 0 {
32			return fmt.Errorf("%w: 整批发行清单不能为空", ErrInvalidArgument)
33		}
34		seen := make(map[string]bool, len(req.Entries))
35		for i, e := range req.Entries {
36			if strings.TrimSpace(e.ItemID) == "" {
37				return fmt.Errorf("%w: 清单第 %d 条缺少藏品编号", ErrInvalidArgument, i+1)
38			}
39			if strings.TrimSpace(e.HolderID) == "" {
40				return fmt.Errorf("%w: 清单第 %d 条（藏品 %s）缺少初始持有人", ErrInvalidArgument, i+1, e.ItemID)
41			}
42			if seen[e.ItemID] {
43				return fmt.Errorf("%w: 清单内藏品编号 %s 重复", ErrInvalidArgument, e.ItemID)
44			}
45			seen[e.ItemID] = true
46		}
47		return nil
48	}
49	
50	func issueBatchParamsSig(req IssueBatchRequest) string {
51		// 条目按提交顺序进入签名：改动任一条目内容或条目顺序都会得到不同
52		// 签名，按请求号冲突拒绝。
53		type entry struct {
54			ItemID   string `json:"item_id"`
55			Metadata string `json:"metadata"`
56			HolderID string `json:"holder_id"`
57		}
58		entries := make([]entry, 0, len(req.Entries))
59		for _, e := range req.Entries {
60			entries = append(entries, entry{e.ItemID, e.Metadata, e.HolderID})
61		}
62		b, _ := json.Marshal(struct {
63			Kind     string  `json:"kind"`
64			SeriesID string  `json:"series_id"`
65			BatchNo  string  `json:"batch_no"`
66			Reason   string  `json:"reason"`
67			Entries  []entry `json:"entries"`
68		}{"issue_batch", req.SeriesID, req.BatchNo, req.Reason, entries})
69		return string(b)
70	}
71	
72	// IssueBatch 由系列创建账户一次提交同一系列、同一批次号下的多件藏品，
73	// 整批共用操作者、原因与请求号。成功后按提交顺序依次为每件建立登记、
74	// 初始持有（版本 1）与发行历史，历史序号连续递增，整批记录之间不会插入
75	// 其他发行或转让；各件随后可通过现有查询读取，并按现有规则转让、创建
76	// 代转授权与计算版税。整批成功同样固定系列的版税规则。
77	//
78	// 空清单、清单内编号重复或必填内容缺失按参数错误拒绝（文字元数据仍可
79	// 为空）；操作者、系列或任一初始持有人未登记按对象不存在拒绝；非系列
80	// 创建账户、系列已封存、操作者或初始持有人停用、任一藏品编号已占用
81	// 沿用单件发行的对应业务拒绝。整批拒绝是原子的：不新增任何藏品、持有
82	// 或发行历史，尚未占用的编号仍可用于后续发行，系列版税规则也不会因此
83	// 固定。
84	//
85	// 请求号与单件发行、转让等操作共用同一操作者的请求号范围：内容与条目
86	// 顺序相同的重复提交回放整批首次结果（成功或状态类业务拒绝）并标明
87	// Replayed；改动原因、系列、批次号、条目顺序或任一条目内容返回
88	// ErrRequestConflict。成功回放仍给出最初的发行结果，即使藏品已转走、
89	// 系列已封存或账户已停用。参数错误与引用不存在不占用请求号，修正后可
90	// 用原号重新提交。
91	//
92	// 状态类拒绝的落盘失败时，返回保存错误（保留实际写入错误）而非该业务
93	// 错误，结果为空（无发行条目、无失败藏品编号、不标回放、业务错误为空），
94	// 请求号不被这次未保存的拒绝占用，任何藏品都不新增登记、持有或发行历史，
95	// 历史序号不被消耗，未首次发行的系列也不因此固定版税规则；保存条件恢复
96	// 后用完全相同的请求重提，按当时的业务状态重新判断：拒绝条件仍在则重新
97	// 保存此次拒绝并返回对应业务错误（这次不算回放），状态已变为满足请求则
98	// 整批正常发行。
99	func (r *Registry) IssueBatch(req IssueBatchRequest) (IssueBatchResult, error) {
100		if err := req.validatePresent(); err != nil {
101			return IssueBatchResult{}, err
102		}
103		r.mu.Lock()
104		defer r.mu.Unlock()
105		if err := r.checkOpen(); err != nil {
106			return IssueBatchResult{}, err
107		}
108	
109		key := requestKey(req.Operator, req.RequestID)
110		sig := issueBatchParamsSig(req)
111		if prev, ok := r.state.Requests[key]; ok {
112			return r.replayIssueBatch(prev, sig)
113		}
114	
115		itemID, bizErr := r.checkIssueBatch(req)
116		if bizErr != nil {
117			if !isValidationErr(bizErr) {
118				// 状态类业务拒绝（封存、停用、无权、编号已用等）占用请求号
119				// 并落盘：相同参数重提永远返回这一次拒绝，即使状态后来变化。
120				r.state.Requests[key] = request{
121					Operator: req.Operator, RequestID: req.RequestID, Kind: "issue_batch",
122					Params: sig, Rejected: true, Reason: errCode(bizErr),
123					ItemID: itemID,
124				}
125				if err := r.commit(); err != nil {
126					// 拒绝结果落盘失败：这次拒绝没有被记住，不能只用业务错误
127					// 掩盖保存错误——调用者稍后用原请求重提时必须按当时状态
128					// 重新判断，而不是回放一个实际没有保存的拒绝。commit 失败
129					// 时已按磁盘内容重建状态，请求记录随之撤销；此处再删一次
130					// 以覆盖磁盘暂时不可读、状态未能重建的情形。整体返回：没有
131					// 发行条目、没有失败藏品编号、不标回放、结果中业务错误为空，
132					// error 保留实际写入错误。
133					delete(r.state.Requests, key)
134					return IssueBatchResult{}, err
135				}
136			}
137			// 校验类错误（引用不存在等）不占用请求号，也不改变任何状态。
138			return IssueBatchResult{ItemID: itemID, Err: bizErr}, bizErr
139		}
140	
141		// 在同一临界区内依次为每件建立登记、持有与发行历史，序号连续递增；
142		// 与其他操作互斥，整批记录之间不会插入其他发行或转让。
143		items := make([]IssueBatchItem, 0, len(req.Entries))
144		stored := make([]batchItemResult, 0, len(req.Entries))
145		for _, e := range req.Entries {
146			seq := r.state.NextSeq + 1
147			r.state.NextSeq = seq
148			r.state.Items[e.ItemID] = item{
149				ID: e.ItemID, SeriesID: req.SeriesID, BatchNo: req.BatchNo,
150				Metadata: e.Metadata, IssuedTxID: seq,
151			}
152			r.state.Holdings[e.ItemID] = holding{ItemID: e.ItemID, OwnerID: e.HolderID, Version: 1}
153			r.state.History = append(r.state.History, historyEntry{
154				Seq: seq, Kind: "issue", ItemID: e.ItemID, Operator: req.Operator,
155				Reason: req.Reason, RequestID: req.RequestID,
156				FromID: "", ToID: e.HolderID, FromVersion: 0, ToVersion: 1,
157			})
158			items = append(items, IssueBatchItem{ItemID: e.ItemID, OwnerID: e.HolderID, Version: 1, TxSeq: seq})
159			stored = append(stored, batchItemResult{ItemID: e.ItemID, OwnerID: e.HolderID, TxSeq: seq})
160		}
161		r.state.Requests[key] = request{
162			Operator: req.Operator, RequestID: req.RequestID, Kind: "issue_batch",
163			Params: sig, Batch: stored,
164		}
165		if err := r.commit(); err != nil {
166			return IssueBatchResult{}, err
167		}
168		return IssueBatchResult{Items: items}, nil
169	}
170	
171	// checkIssueBatch 按整批发行的优先级执行与单件共用的发行资格规则。
172	// 返回业务拒绝所涉及的藏品编号（操作者或系列层面的问题与具体某件无关，
173	// 返回空）与错误本身；编号占用始终优先于初始持有人问题，同一类问题报告
174	// 清单顺序最前的那件。任何一件不通过则整批拒绝。
175	func (r *Registry) checkIssueBatch(req IssueBatchRequest) (string, error) {
176		return r.checkBatchIssueEligibility(req.Operator, req.SeriesID, req.Entries)
177	}
178	
179	func (r *Registry) replayIssueBatch(prev request, sig string) (IssueBatchResult, error) {
180		if prev.Kind != "issue_batch" || prev.Params != sig {
181			return IssueBatchResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
182				ErrRequestConflict, prev.Operator, prev.RequestID)
183		}
184		res := IssueBatchResult{ItemID: prev.ItemID, Replayed: true}
185		if prev.Rejected {
186			res.Err = codeErr(prev.Reason)
187			return res, res.Err
188		}
189		// 回放整批首次成功的发行结果：即使藏品后来已转走、系列已封存或账户
190		// 已停用，仍返回最初的持有人与历史序号，不改写当前状态。
191		for _, bi := range prev.Batch {
192			res.Items = append(res.Items, IssueBatchItem{
193				ItemID: bi.ItemID, OwnerID: bi.OwnerID, Version: 1, TxSeq: bi.TxSeq,
194			})
195		}
196		return res, nil
197	}
